/**
 * get browser info
 * @returns {{
 *   isIpad: boolean,
 *   isWeixin: boolean,
 *   isEdge: boolean,
 *   isIE: boolean,
 *   ieVersion: string,
 *   userAgent: string,
 *   isIphone: boolean,
 *   isQQ: boolean,
 *   isWeibo: boolean,
 *   isAndroid: boolean
 * }}
 */
export default (() => {
  var ua = navigator.userAgent;
  var isIE = /compatible/gi.test(ua) && /MSIE/gi.test(ua);
  var isEdge = /Edge/gi.test(ua) && !isIE;
  var isIE11 = /Trident/gi.test(ua) && /rv:11\.0/gi.test(ua);
  return {
    userAgent: ua,
    isAndroid: /Android/gi.test(ua),
    isIphone: /iPhone|ipod/gi.test(ua),
    isIpad: /iPad/gi.test(ua),
    isWeixin: /MicroMessenger/gi.test(ua),
    isQQ: /QQ/gi.test(ua),
    isWeibo: /WeiBo/gi.test(ua),
    isIE: isIE || isIE11,
    isEdge,
    ieVersion: (() => {
      if (isIE11) {
        return '11';
      }
      if (isEdge) {
        return 'edge';
      }
      if (isIE) {
        var reIE = /MSIE (\d+\.\d+);/;
        reIE.test(ua);
        var fIEVersion = parseFloat(RegExp.$1);
        switch (fIEVersion) {
          case 6:
          case 7:
          case 8:
          case 9:
          case 10:
            return "".concat(fIEVersion);
          default:
            return '<6';
        }
      }
      return '-1';
    })()
  };
});